# ======================================================================
# Static guard: no lock-taking helper called from inside the critical section
# ======================================================================


def _source_files():
    app_dir = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "app")
    for root, _dirs, names in os.walk(app_dir):
        for n in sorted(names):
            if n.endswith(".py"):
                yield os.path.join(root, n)


def test_no_nested_lock_acquisition_in_app_package():
    """Mechanically forbid taking the store lock while already holding it.

    ``threading.Lock`` is not reentrant, so any ``store.read``/``store.transaction``
    that executes inside another one's ``work`` callback blocks the thread
    forever. That single mistake is the most dangerous thing in this codebase,
    and it is invisible to review because both call sites look correct on their
    own, so it is rejected here by AST rather than by eye.
    """
    import ast

    lock_takers = {"read", "transaction", "_locked_read"}
    offenders = []

    for path in _source_files():
        with open(path, "rb") as fh:
            tree = ast.parse(fh.read(), filename=path)
        rel = os.path.relpath(path, os.path.dirname(path))

        # Map every function that is passed as a `work`/`fn` argument so we can
        # resolve `store.read(my_helper)` to "my_helper runs with the lock held".
        callbacks: dict[str, str] = {}
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute):
                continue
            if node.func.attr not in lock_takers:
                continue
            for arg in list(node.args) + [kw.value for kw in node.keywords]:
                if isinstance(arg, ast.Name):
                    callbacks[arg.id] = node.func.attr
                elif isinstance(arg, ast.Lambda):
                    offenders.append(
                        f"{rel}:{arg.lineno}: inline lambda passed to "
                        f"store.{node.func.attr}() - inline callbacks cannot be checked"
                    )

        # Direct nesting: a lock taker called from inside another lock taker's
        # inline callback, or a lock taker inside a known lock-holding helper.
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute):
                continue
            if node.func.attr not in lock_takers:
                continue
            parent_fn = None
            for cand in ast.walk(tree):
                if isinstance(cand, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    for sub in ast.walk(cand):
                        if sub is node:
                            parent_fn = cand
                            break
                if parent_fn is not None:
                    break
            if parent_fn is not None and parent_fn.name in lock_takers:
                offenders.append(
                    f"{rel}:{node.lineno}: store.{node.func.attr}() called inside "
                    f"store.{parent_fn.name}() - the lock is already held"
                )

        # Indirect nesting: a helper that takes the lock being called from a
        # function that is itself used as a lock-holding callback.
        for name, holder in callbacks.items():
            for node in ast.walk(tree):
                if not isinstance(node, ast.Call):
                    continue
                target = node.func.attr if isinstance(node.func, ast.Attribute) else (
                    node.func.id if isinstance(node.func, ast.Name) else None
                )
                if target == name:
                    owner = None
                    for cand in ast.walk(tree):
                        if isinstance(cand, (ast.FunctionDef, ast.AsyncFunctionDef)):
                            if any(sub is node for sub in ast.walk(cand)):
                                owner = cand.name
                                break
                        if owner:
                            break
                    if owner and owner != holder and _takes_lock(tree, owner, lock_takers):
                        offenders.append(
                            f"{rel}:{node.lineno}: {owner}() calls {name}() which takes the "
                            f"lock, but {owner}() is itself the callback for store.{holder}()"
                        )

    assert not offenders, "nested store-lock acquisition detected:\n  " + "\n  ".join(offenders)


def _takes_lock(tree, func_name, lock_takers) -> bool:
    for cand in ast.walk(tree):
        if isinstance(cand, (ast.FunctionDef, ast.AsyncFunctionDef)) and cand.name == func_name:
            for sub in ast.walk(cand):
                if isinstance(sub, ast.Call) and isinstance(sub.func, ast.Attribute):
                    if sub.func.attr in lock_takers:
                        return True
    return False


